
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"HotFruits20AM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
			
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.ben.ngk!=undefined){
			
			if(gameController.sbg!=parseInt(tmpMess[1])){
				
			gameController.sbg=parseInt(tmpMess[1]);	
				
			gameController.ben.ngk("tbd", "#setText", [gameController.eow(tmpMess[1]),true])
				
			}
			
			
			
			
			
			}	
			
		}
		
